Suppose \[{\mathbf{A}}^{(t)}\] is \[\epsilon_t\]-close to \[{\mathbf{A}}^*\]. Then, if \[\mu = {\mathcal{O}}(\log(n))\], \[k = \sqrt{n}/\mu\log(n)\], and \[\epsilon_t = \mathcal{O}^*(1/\sqrt{\log(m)})\], with probability at least \[(1 - \delta_{{{\mathcal{T}}}}^{(t)})\] for each random sample \[{\mathbf{y}} = {\mathbf{A}}^*{\mathbf{x}}^*\]:
	\begin{align*}
	{\rm sign}({{\mathcal{T}}}_{C/2}(({\mathbf{A}}^{(t)})^\top {\mathbf{y}}) = {\rm sign}({\mathbf{x}}^*),
	\end{align*}

	where \[\delta_{{{\mathcal{T}}}}^{(t)} = 2m~{\exp}({-\tfrac{C^2}{\mathcal{O}^*(\epsilon_t^2)}})\].

\begin{em}
	With probability \[(1-\delta_{\beta}^{(t)})\], \[|\beta^{(t)}_j|\] is upper-bounded by \[t_\beta = \mathcal{O}(\sqrt{k\epsilon_t})\], where \[\delta_{\beta}^{(t)} = 2k~{\exp}(-\tfrac{1}{\mathcal{O}(\epsilon_t)})\].
\end{em}

Suppose \[{\mathbf{A}}^{(t)}\] is \[\epsilon_t\]-close to \[{\mathbf{A}}^*\],  \[\mu = {\mathcal{O}}(\log(n))\], \[k = \sqrt{n}/\mu\log(n)\], and \[\epsilon_t = \mathcal{O}^*(1/\log(m))\] Then, with probability at least \[(1 - \delta_{\beta}^{(t)} - \delta_{{{\mathcal{T}}}}^{(t)}  )\], each iterate of the IHT-based coefficient update step shown in (5) has the correct signed-support, if for a constant \[c^{(r)}_1(\epsilon_t, \mu, k, n) = \widetilde{\Omega}({k^2}/{n})\], the step size is chosen as \[\eta_x^{(r)}\leq c^{(r)}_1\] ,






	and the threshold \[\tau^{(r)}\] is chosen as
	\begin{align*}
	\tau^{(r)} = \eta_x^{(r)}(t_\beta + \tfrac{\mu_t}{\sqrt{n}} \|{\mathbf{x}}^{(r-1)} - {\mathbf{x}}^*\|_1) :=c_2^{(r)}(\epsilon_t, \mu, k, n) = \widetilde{\Omega}({k^2}/{n}),
	\end{align*}

	for some constants \[c_1\] and \[c_2\]. Here, \[t_\beta = \mathcal{O}(\sqrt{k\epsilon_t})\], \[\delta_{{{\mathcal{T}}}}^{(t)} = 2m~{\exp}({-\tfrac{C^2}{\mathcal{O}^*(\epsilon_t^2)}})\] ,and \[\delta_{\beta}^{(t)} = 2k~{\exp}(-\tfrac{1}{\mathcal{O}(\epsilon_t)})\].

\begin{em}
The error in a general iterate \[r\]  of the coefficient estimation is upper-bounded as
	\begin{align*}
	C_{i_1}^{(r+1)} 
	&\leq \alpha^{(r+1)}_{i_1} + (k-1)\eta_x\tfrac{\mu_t}{\sqrt{n}} \textstyle\sum\limits_{\ell = 1}^{r}  \alpha^{(\ell)}_{\max}\big(1-\eta_x + \eta_x\tfrac{\mu_t}{\sqrt{n}} \big)^{r -\ell}
	\\&\hspace{7cm}+ (k-1)\eta_x\tfrac{\mu_t}{\sqrt{n}}C_{\max}^{(0)} \big(1-\eta_x + \eta_x\tfrac{\mu_t}{\sqrt{n}} \big)^r.
	\end{align*}

	\end{em}

\begin{em}
	With probability \[(1 -\delta_{{{\mathcal{T}}}}^{(t)}-\delta_{\beta}^{(t)})\],
	\begin{align*}
	\textstyle\sum\limits_{\ell = 1}^{{R}}  \alpha^{(\ell)}_{\max}\big(1-\eta_x + \eta_x\tfrac{\mu_t}{\sqrt{n}} \big)^{{R} -\ell} \leq C_i^{(0)}{R}\delta_{R}  + \tfrac{1}{\eta_x( 1- \tfrac{\mu_t}{\sqrt{n}})}(\tfrac{\epsilon_t^2}{2} |{\mathbf{x}}_{\max}^*| +t_\beta).
	\end{align*}
	\end{em}

\begin{em}
	With probability \[(1-\delta_{\beta}^{(t)})\], each entry \[\vartheta^{(R)}_{i_1}\] of \[\vartheta^{(R)}\] is upper-bounded as
	\begin{align*}
	|\vartheta^{(R)}_{i_1}| 
	& \leq  \mathcal{O}(t_{\beta}).
	\end{align*}

	\end{em}

With probability at least \[(1 - \delta_{{\mathcal{T}}}^{(t)} - \delta_{\beta}^{(t)})\] the \[i_1\]-th element of the coefficient estimate, for each \[i_1 \in {\rm supp}({\mathbf{x}}^*)\], is given by
 	\begin{align*}
 	\widehat{{\mathbf{x}}}_{i_1} := {\mathbf{x}}_{i_1}^{(R)} =  {\mathbf{x}}_{i_1}^* (1 - \lambda^{(t)}_{i_1}) + \vartheta^{(R)}_{i_1}.
 	\end{align*}

 	Here, \[\vartheta^{(R)}_{i_1}\] is \[|\vartheta^{(R)}_{i_1}| = \mathcal{O}(t_{\beta})\], 

 	where \[t_\beta = \mathcal{O}(\sqrt{k\epsilon_t})\]. Further, \[\lambda^{(t)}_{i_1} = |\langle {\mathbf{A}}^{(t)}_{i_1}- {\mathbf{A}}^{*}_{i_1}, {\mathbf{A}}^*_{i_1}\rangle| \leq \tfrac{\epsilon_t^2}{2}\], \[\delta_{{{\mathcal{T}}}}^{(t)} = 2m~{\exp}({-\tfrac{C^2}{\mathcal{O}^*(\epsilon_t^2)}})\] and \[\delta_{\beta}^{(t)} = 2k~{\exp}(-\tfrac{1}{\mathcal{O}(\epsilon_t)})\].

Suppose that \[{\mathbf{A}}^{(t)}\] is \[(\epsilon_t, 2)\]-near to \[{\mathbf{A}}^*\]. Then, the dictionary update step in Algorithm~alg:main_alg amounts to the following for the \[j\]-th dictionary element
	\vspace{-5pt}
		\begin{align*}
		{\mathbf{E}}[{\mathbf{A}}^{(t+1)}_j] = {\mathbf{A}}^{(t)}_j + \eta_A {\mathbf{g}}^{(t)}_j,
		\vspace{-5pt}
		\end{align*}	
		where \[{\mathbf{g}}^{(t)}_j\] is given by
			\vspace{-5pt}
		\begin{align*}
		{\mathbf{g}}^{(t)}_j = q_j p_j \big((1 - \lambda^{(t)}_j){\mathbf{A}}^{(t)}_j- {\mathbf{A}}^*_j + \tfrac{1}{q_j p_j}\Delta^{(t)}_j \pm \gamma\big),
		\end{align*}










	\[\lambda^{(t)}_{j}=|\langle {\mathbf{A}}^{(t)}_j - {\mathbf{A}}^{*}_j, {\mathbf{A}}^*_j\rangle|\], and \[\Delta^{(t)}_j:={\mathbf{E}}[{\mathbf{A}}^{(t)}_S\vartheta^{(R)}_S{\rm sign}({\mathbf{x}}^*_j)]\], where \[\|\Delta^{(t)}_{j}\|= \mathcal{O}(\sqrt{m}q_{i,j}p_{j}\epsilon_t\|{\mathbf{A}}^{(t)}\|)\].

For \[c_x = {\tfrac{\mu_t}{\sqrt{n}}}/{(1 - \tfrac{\mu_t}{\sqrt{n}})}\], we have 
	\begin{align*}
	C_{i_2}^{(r-1)} (1- \eta_x)^{{R} - r}\hspace{-5pt}
	\leq (\lambda^{(t)}_{\max} |{\mathbf{x}}_{\max}^*| +\beta^{(t)}_{\max}) \bigg[ \textstyle\sum\limits_{s=1}^{r-1}\eta_x(1- \eta_x)^{{R} - s} &+ 
	kc_x(1- \eta_x)^{{R} - r}\bigg] \\&+ k\eta_x\tfrac{\mu_t}{\sqrt{n}}C_{\max}^{(0)} \delta_{{R}-2}.
	\end{align*}

\begin{em}
   \[\|\Delta^{(t)}_{j}\|\] where \[\Delta^{(t)}_{j}:= {\mathbf{E}}[{\mathbf{A}}^{(t)}\vartheta^{(R)}{\rm sign}({\mathbf{x}}^*_{j})] \] is upper-bounded as,
	\begin{align*}
	\|\Delta^{(t)}_{j}\| = \mathcal{O}(\sqrt{m}q_{i,j}p_{j}\epsilon_t\|{\mathbf{A}}^{(t)}\|)].
	\end{align*}
\end{em}

Given \[p = \widetilde{\Omega}(mk^2)\] samples, the empirical gradient vector estimate corresponding to the \[i\]-th dictionary element, \[\widehat{{\mathbf{g}}}_i^{(t)}\] concentrates around its expectation, i.e.,
		\begin{align*}
		\|\widehat{{\mathbf{g}}}_i^{(t)} - {\mathbf{g}}_i^{(t)}\| \leq o(\tfrac{k}{m}\epsilon_t).
		\end{align*}

		with probability at least \[(1 -\delta_{{\mathbf{g}}_i}^{(t)}- \delta_{\beta}^{(t)} - \delta_{{{\mathcal{T}}}}^{(t)} - \delta_{\rm HW}^{(t)})\], where \[\delta_{{\mathbf{g}}_i}^{(t)} =  \exp(-\Omega(k))\].

\begin{em}
	With probability \[(1 - \delta_{\beta}^{(t)} - \delta_{{{\mathcal{T}}}}^{(t)} - \delta_{\rm HW}^{(t)})\] \[\|{\mathbf{y}}-{\mathbf{A}}^{(t)}\widehat{{\mathbf{x}}}\|\] is upper-bounded by  
	\[{\color{black}{\widetilde{\mathcal{O}}(kt_{\beta})}}\] .
	\end{em}

\begin{em}
	For  \[{\mathbf{z}}:= ({\mathbf{y}}- {\mathbf{A}}^{(t)}\widehat{{\mathbf{x}}}){\rm sign}(\widehat{{\mathbf{x}}}_i)|i\in S\] the variance parameter  \[{\mathbf{E}}[\|{\mathbf{z}}\|^2]\] is bounded as

    \[{\mathbf{E}}[\|{\mathbf{z}}\|^2] = \mathcal{O}(k\epsilon_t^2) +

    {\color{black}{ \mathcal{O}( kt_{\beta}^2)}}\] with probability at least \[(1 - \delta_{\beta}^{(t)} - \delta_{{{\mathcal{T}}}}^{(t)})\].
    \end{em}

Suppose \[{\mathbf{A}}^{(t)}\] is \[(\epsilon_t, 2)\]-near to \[{\mathbf{A}}^*\], \[k = \mathcal{O}(\sqrt{n})\] and \[\eta_A = \mathcal{O}(m/k)\]. Then, with probability at least \[(1 - \delta_{{{\mathcal{T}}}}^{(t)} - \delta_{\beta}^{(t)} - \delta_{\rm HW}^{(t)} -\delta_{{\mathbf{g}}_i}^{(t)})\] the empirical gradient vector \[\widehat{{\mathbf{g}}}^{(t)}_j\] 




	 is \[(\Omega(k/m), \Omega(m/k),0 )\]-correlated with \[({\mathbf{A}}^{(t)}_j - {\mathbf{A}}^*_j)\], and for any \[t \in [T]\],
	\begin{align*}
	\|{\mathbf{A}}^{(t+1)}_j- {\mathbf{A}}^*_j\|^2 \leq (1 - \rho_{\_}\eta_A)\|{\mathbf{A}}^{(t)}_j- {\mathbf{A}}^*_j\|^2.
	\end{align*}

\begin{em}
With probability \[(1-\delta_{{{\mathcal{T}}}}^{(t)} - \delta_{\beta}^{(t)})\], the variance parameter
	\[\|\mathbf{E}[({\mathbf{y}}-{\mathbf{A}}^{(t)}\widehat{{\mathbf{x}}}) ({\mathbf{y}}-{\mathbf{A}}\widehat{{\mathbf{x}}})^\top]\|\] is upper-bounded by 
	\[\mathcal{O}(\tfrac{k^2t_{\beta}^2}{m})\|{\mathbf{A}}^*\|^2\].
	\end{em}

\textit{Suppose that assumptions assumption:mu-assumption:step coeff  hold, and Algorithm~alg:main_alg is provided with  \[ p = \widetilde{\Omega}(mk^2)\] new samples generated according to model (1) at each iteration \[t\]. 
Then,  with probability at least \[(1 - \delta_{\text{alg}}^{(t)})\] for some small constant \[\delta_{\text{alg}}^{(t)}\], given \[R = \Omega({\rm log}(n))\], the coefficient estimate \[\widehat{{\mathbf{x}}}_{i}^{(t)}\] at \[t\]-th iteration has the correct signed-support and satisfies
\vspace{-2pt}
\begin{align*}
(\widehat{{\mathbf{x}}}_{i}^{(t)} - {\mathbf{x}}_{i}^*)^2 
&= \mathcal{O}(k(1 - \omega)^{t/2}\|{\mathbf{A}}_i^{(0)} - {\mathbf{A}}_i^*\|), ~\text{for all}~i \in {\rm supp}({{\mathbf{x}}^*}).\vspace{-2pt}


\end{align*} 
Furthermore, for some \[0 < \omega < 1/2\], the estimate \[{\mathbf{A}}^{(t)}\] at \[(t)\]-th iteration satisfies 
\vspace{-2pt}
\begin{align*}
\|{\mathbf{A}}_i^{(t)} - {\mathbf{A}}_i^*\|^2 \leq (1 - \omega)^t\|{\mathbf{A}}_i^{(0)} - {\mathbf{A}}_i^*\|^2,~\text{for all}~t = 1,2,\ldots.\vspace{-2pt} .
\end{align*}
}
